insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','local','A guest has chest pain late at night and their friend wants to drive them. Which of these is a 24-hour emergency department?','Un huésped tiene dolor de pecho tarde en la noche y un amigo quiere llevarlo. ¿Cuál de estos es un departamento de emergencias 24 horas?','["M Health Fairview Southdale Hospital – Emergency", "CVS Pharmacy (Richfield)", "TRIA Orthopedic Urgent Care Bloomington", "M Health Fairview Urgent Care – Oxboro"]'::jsonb,'["M Health Fairview Southdale Hospital – Emergency", "CVS Pharmacy (Richfield)", "TRIA Orthopedic Urgent Care Bloomington", "M Health Fairview Urgent Care – Oxboro"]'::jsonb,0,'M Health Fairview Southdale Hospital – Emergency is a 24-hour ER, about 7.0 miles away. Urgent care clinics close at night. For chest pain, the safest advice is to call 911.','M Health Fairview Southdale Hospital – Emergency es una sala de emergencias 24 horas, a unas 7.0 millas. Las clínicas de urgencias cierran de noche. Ante dolor de pecho, lo más seguro es llamar al 911.','https://www.mhealthfairview.org/locations/emergency-department---m-health-fairview-southdale-hospital',array['front_desk','night_audit']::text[],'role','med',array['hotel','local','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','local','A guest twisted an ankle and wants the closest walk-in clinic or hospital. Which of these is closest by car?','Un huésped se torció el tobillo y quiere la clínica sin cita u hospital más cercano. ¿Cuál de estos está más cerca en auto?','["M Health Fairview Southdale Hospital – Emergency", "M Health Fairview Urgent Care – Oxboro", "TRIA Orthopedic Urgent Care Bloomington", "Hennepin Healthcare (HCMC) Emergency"]'::jsonb,'["M Health Fairview Southdale Hospital – Emergency", "M Health Fairview Urgent Care – Oxboro", "TRIA Orthopedic Urgent Care Bloomington", "Hennepin Healthcare (HCMC) Emergency"]'::jsonb,1,'M Health Fairview Urgent Care – Oxboro is about 4.6 miles away, closer than the others. Check its posted hours on the Directory card.','M Health Fairview Urgent Care – Oxboro está a unas 4.6 millas, más cerca que los demás. Revisa su horario en la tarjeta del Directorio.','https://www.mhealthfairview.org/locations/m-health-fairview-urgent-care---oxboro',array['front_desk','night_audit']::text[],'role','med',array['hotel','local','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','local','A guest returning a rental car needs gas late at night. Which 24-hour station on our list is closest?','Un huésped que devuelve un auto rentado necesita gasolina tarde en la noche. ¿Qué gasolinera 24 horas de nuestra lista está más cerca?','["Holiday (84th & Lyndale)", "Holiday (98th St)", "Speedway (86th & Lyndale)", "Target Field"]'::jsonb,'["Holiday (84th & Lyndale)", "Holiday (98th St)", "Speedway (86th & Lyndale)", "Target Field"]'::jsonb,0,'Holiday (84th & Lyndale) is about 4.1 miles away and listed as 24 hours.','Holiday (84th & Lyndale) está a unas 4.1 millas y aparece abierta las 24 horas.','https://www.circlek.com/us/holiday-station/store-locator/US/bloomington/8401-lyndale-ave-s/2746073',array['driver','front_desk','night_audit']::text[],'role','easy',array['hotel','local','mspms','driver']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','local','A guest wants to ride the light rail. Which station is closest to our hotel?','Un huésped quiere usar el tren ligero. ¿Qué estación está más cerca de nuestro hotel?','["Metro Transit Route 9 (Golden Hills Dr)", "Blue Line – American Boulevard station", "Target Field Station (Blue/Green Line)", "Mall of America Transit Station"]'::jsonb,'["Metro Transit Route 9 (Golden Hills Dr)", "Blue Line – American Boulevard station", "Target Field Station (Blue/Green Line)", "Mall of America Transit Station"]'::jsonb,1,'Blue Line – American Boulevard station is about 0.6 miles by car. Closest light-rail stop; north to the airport and downtown, south to MOA.','Blue Line – American Boulevard station está a unas 0.6 millas en auto. La estación de tren más cercana; al norte aeropuerto y centro, al sur MOA.','https://www.metrotransit.org/Schedules/RouteMaps/jun26/blue',array['driver','front_desk','night_audit']::text[],'role','easy',array['hotel','local','mspms','driver']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','local','A guest''s dog ate something toxic at 11 p.m. Which of these is a 24-hour animal emergency hospital?','El perro de un huésped comió algo tóxico a las 11 p.m. ¿Cuál de estos es un hospital veterinario de emergencias 24 horas?','["TRIA Orthopedic Urgent Care Bloomington", "Banfield Pet Hospital Bloomington", "CVS Pharmacy (Richfield)", "South Metro Animal Emergency Care (Apple Valley)"]'::jsonb,'["TRIA Orthopedic Urgent Care Bloomington", "Banfield Pet Hospital Bloomington", "CVS Pharmacy (Richfield)", "South Metro Animal Emergency Care (Apple Valley)"]'::jsonb,3,'South Metro Animal Emergency Care (Apple Valley) is listed as 24 hours, about 10.3 miles away. Phone: 952-953-3737.','South Metro Animal Emergency Care (Apple Valley) aparece abierto las 24 horas, a unas 10.3 millas. Teléfono: 952-953-3737.','https://smaec.com/',array['front_desk','night_audit']::text[],'role','med',array['hotel','local','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
